/**
 * AwaVote Nano text featuriser — MUST stay bit-identical to ai/intent/featurizer.py.
 * Guarded by parity_vectors.json (generated by the Python trainer) in tests.
 */
export const DIM = 4096;
const CHAR_N = [2, 3, 4];
const FOLD = { "ɗ": "d", "ƙ": "k", "ɓ": "b", "ƴ": "y", "ʼ": "'" };
const MARK = /\p{M}/u;
const ALNUM = /[\p{L}\p{N}]/u;

export function normalize(text) {
  let out = "";
  for (let ch of text.normalize("NFD").toLowerCase()) {
    if (MARK.test(ch)) continue;
    ch = FOLD[ch] ?? ch;
    out += ALNUM.test(ch) ? ch : " ";
  }
  return out.split(" ").filter(Boolean).join(" ");
}

export function fnv1a(str) {
  let h = 0x811c9dc5;
  for (const b of new TextEncoder().encode(str)) {
    h ^= b;
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h >>> 0;
}

export function tokens(text) {
  const norm = normalize(text);
  const cps = Array.from(` ${norm} `); // code points, to match Python string slicing
  const feats = [];
  for (const n of CHAR_N) for (let i = 0; i + n <= cps.length; i++) feats.push("c" + cps.slice(i, i + n).join(""));
  const words = norm ? norm.split(" ") : [];
  for (const w of words) feats.push("w" + w);
  for (let i = 0; i + 1 < words.length; i++) feats.push("b" + words[i] + "_" + words[i + 1]);
  return feats;
}

/** Returns a sparse map {index: value} (handy for tests) */
export function featurizeSparse(text, dim = DIM) {
  const counts = new Map();
  for (const f of tokens(text)) {
    const i = fnv1a(f) % dim;
    counts.set(i, (counts.get(i) || 0) + 1);
  }
  let norm = 0;
  const vals = new Map();
  for (const [i, c] of counts) { const v = Math.log1p(c); vals.set(i, v); norm += v * v; }
  norm = Math.sqrt(norm) || 1;
  for (const [i, v] of vals) vals.set(i, v / norm);
  return vals;
}

export function featurize(text, dim = DIM) {
  const x = new Float32Array(dim);
  for (const [i, v] of featurizeSparse(text, dim)) x[i] = v;
  return x;
}
